class Solution:
    def sequenceReconstruction(self, nums: list[int], sequences: list[list[int]]) -> bool:
        allowed = set(nums)
        present = set()
        g = {x: set() for x in nums}
        for seq in sequences:
            for x in seq:
                if x not in allowed:
                    return False
                present.add(x)
            for a, b in zip(seq, seq[1:]):
                g[a].add(b)
        if present != allowed:
            return False
        pos = {x: i for i, x in enumerate(nums)}
        for a in g:
            for b in g[a]:
                if pos[a] >= pos[b]:
                    return False
        for a, b in zip(nums, nums[1:]):
            seen = {a}; stack = [a]; found = False
            while stack and not found:
                u = stack.pop()
                for v in g[u]:
                    if v == b:
                        found = True; break
                    if v not in seen:
                        seen.add(v); stack.append(v)
            if not found:
                return False
        return True

solutions.better:
class Solution:
    def sequenceReconstruction(self, nums: list[int], sequences: list[list[int]]) -> bool:
        pos = {x: i for i, x in enumerate(nums)}
        need = {(nums[i], nums[i + 1]) for i in range(len(nums) - 1)}
        seen = set()
        for seq in sequences:
            for x in seq:
                if x not in pos:
                    return False
                seen.add(x)
            for a, b in zip(seq, seq[1:]):
                if pos[a] >= pos[b]:
                    return False
                need.discard((a, b))
        return not need and seen == set(nums)

